//! Bindings generated by fil-rust-bindgen from `fixtures/api.h`
//! (`tests/generated/api.rs`; the fil-rust-bindgen tests check it is up to
//! date) used against the library built from `fixtures/api.c`.

mod common;

use std::ffi::c_char;
use std::sync::{Arc, Mutex};

include!("generated/api.rs");

use api_ffi::*;
use common::{fixture, runtime};
use fil_rust::{Callback, FilFn, FilPtr, Ptr};

/// Held by the tests that change the library's globals, which the
/// `opaque_handles_and_structs_with_pointers` test checks. Taken outside
/// `run`, since a thread must not block while it is in Fil-C.
static GLOBALS: Mutex<()> = Mutex::new(());

fn load(fil: &fil_rust::Fil<'_>) -> Api {
    Api::load(fil, fixture("api.c")).expect("loading api.c")
}

/// A shape built in Rust; the pointers live in the current scope.
fn square<'f>(fil: &fil_rust::Fil<'f>, name: &str, side: f64, origin: vec2) -> shape<'f> {
    let corners = [vec2 { x: 0.0, y: 0.0 }, vec2 { x: side, y: 0.0 }, vec2 { x: side, y: side }, vec2 { x: 0.0, y: side }];
    shape {
        kind: SHAPE_RECT,
        name: fil.c_str(name).unwrap(),
        origin,
        points: fil.alloc_array::<vec2>(&corners).unwrap(),
        npoints: corners.len(),
        fill: color { r: 255, g: 0, b: 0, a: 255 },
        tags: [1, 2, 3, 4],
        visible: true,
    }
}

#[test]
fn constants_and_enums() {
    assert_eq!(API_VERSION, 3);
    assert_eq!(API_NAME, b"api\0");
    assert_eq!((SHAPE_CIRCLE, SHAPE_RECT, SHAPE_TRIANGLE), (0, 5, 6));
    let _: shape_kind = SHAPE_TRIANGLE;
}

#[test]
fn structs_by_value() {
    runtime().run(|fil| {
        let api = load(fil);
        let v = api.vec2_add(fil, vec2 { x: 1.0, y: 2.0 }, vec2 { x: 10.0, y: 20.0 }).unwrap();
        assert_eq!((v.x, v.y), (11.0, 22.0));
        let c = api.color_mix(fil, color { r: 100, g: 0, b: 50, a: 255 }, color { r: 200, g: 100, b: 50, a: 255 }).unwrap();
        assert_eq!((c.r, c.g, c.b, c.a), (150, 50, 50, 255));
    });
}

#[test]
fn opaque_handles_and_structs_with_pointers() {
    let _globals = GLOBALS.lock().unwrap();
    runtime().run(|fil| {
        let api = load(fil);
        let reg: FilPtr<'_, registry> = api.registry_new(fil).unwrap();
        for (i, side) in [1.0, 2.0, 3.0].into_iter().enumerate() {
            let s = fil.alloc::<shape>(&square(fil, &format!("sq{i}"), side, vec2 { x: i as f64, y: 0.0 })).unwrap();
            assert_eq!(api.registry_add(fil, reg, s).unwrap(), i as i32);
            assert_eq!(api.shape_area(fil, s).unwrap(), side * side);
            assert!(api.is_kind(fil, s, SHAPE_RECT).unwrap());
        }
        assert_eq!(api.registry_len(fil, reg).unwrap(), 3);

        // A struct read back from C memory, with its nested pointers.
        let second = api.registry_get(fil, reg, 1).unwrap().read(fil).unwrap();
        assert_eq!(second.name.read_string(fil).unwrap(), "sq1");
        assert_eq!(second.points.read_at(fil, 2).unwrap().x, 2.0);
        assert_eq!(second.tags, [1, 2, 3, 4]);
        assert!(second.visible);
        assert!(api.registry_get(fil, reg, 3).unwrap().is_null());

        // A large struct returned by value.
        let b: bbox = api.registry_bounds(fil, reg).unwrap();
        assert_eq!((b.min_x, b.min_y, b.max_x, b.max_y, b.count), (0.0, 0.0, 5.0, 3.0, 12));

        // Globals.
        assert!(api.api_call_count(fil).read(fil).unwrap() >= 4);
        assert_eq!(api.api_last_name(fil).read(fil).unwrap().read_string(fil).unwrap(), "sq2");

        // A shape without a name is rejected by C, not by a crash.
        let mut nameless = square(fil, "x", 1.0, vec2 { x: 0.0, y: 0.0 });
        nameless.name = FilPtr::null();
        assert_eq!(api.registry_add(fil, reg, fil.alloc::<shape>(&nameless).unwrap()).unwrap(), -1);
        api.registry_free(fil, reg).unwrap();
    });
}

#[test]
fn function_pointer_typedefs_are_callbacks() {
    let _globals = GLOBALS.lock().unwrap();
    runtime().run(|fil| {
        let api = load(fil);
        let reg = api.registry_new(fil).unwrap();
        for side in [1.0, 2.0, 4.0] {
            let s = fil.alloc::<shape>(&square(fil, "s", side, vec2 { x: 0.0, y: 0.0 })).unwrap();
            api.registry_add(fil, reg, s).unwrap();
        }

        // `shape_visitor` is a plain `fn` type, so it works with `Callback`.
        // The `void* user` argument carries a Fil-C object of our choosing.
        let visit = Callback::<shape_visitor>::new(fil, |fil, (s, user)| {
            let s = s.read(fil).unwrap();
            let scale = user.cast::<i32>().read(fil).unwrap();
            (s.points.read_at(fil, 1).unwrap().x as i32) * scale
        })
        .unwrap();
        let scale = fil.alloc::<i32>(&10).unwrap();
        assert_eq!(api.registry_visit(fil, reg, visit.get(fil), scale.cast()).unwrap(), 70);

        // Function pointers as struct fields.
        let done = Arc::new(Mutex::new(None));
        let d2 = done.clone();
        let big = Callback::<shape_visitor>::new(fil, |fil, (s, _)| (api_area(fil, s) > 2.0) as i32).unwrap();
        let on_done = Callback::<fn(i32)>::new(fil, move |_, (n,)| *d2.lock().unwrap() = Some(n)).unwrap();
        let set = visitor_set { on_shape: big.get(fil), on_done: on_done.get(fil) };
        let n = api.registry_visit_all(fil, reg, fil.alloc::<visitor_set>(&set).unwrap()).unwrap();
        assert_eq!(n, 2);
        assert_eq!(*done.lock().unwrap(), Some(2));

        // A null function pointer field is allowed where C checks for it.
        let set = visitor_set { on_shape: big.get(fil), on_done: FilFn::null() };
        assert_eq!(api.registry_visit_all(fil, reg, fil.alloc::<visitor_set>(&set).unwrap()).unwrap(), 2);
        // Calling a null function pointer from Rust is an error.
        assert!(set.on_done.is_null());
        assert!(set.on_done.call(fil, (1,)).is_err());
        api.registry_free(fil, reg).unwrap();
    });
}

/// Area of a shape, computed in Rust from its points.
fn api_area<'f>(fil: &fil_rust::Fil<'f>, s: FilPtr<'f, shape<'static>>) -> f64 {
    let s = s.read(fil).unwrap();
    let pts = s.points.read_array(fil, s.npoints).unwrap();
    let twice: f64 = (0..pts.len()).map(|i| {
        let (a, b) = (pts[i], pts[(i + 1) % pts.len()]);
        a.x * b.y - b.x * a.y
    }).sum();
    twice.abs() / 2.0
}

#[test]
fn self_referential_lists_and_void_pointers() {
    runtime().run(|fil| {
        let api = load(fil);
        let mut tags = Vec::new();
        let mut node = api.tags_split(fil, fil.c_str("red,green,,blue").unwrap()).unwrap();
        while !node.is_null() {
            let n: tag_node = node.read(fil).unwrap();
            tags.push(n.tag.read_string(fil).unwrap());
            node = n.next;
        }
        assert_eq!(tags, ["red", "green", "", "blue"]);

        let values = fil.alloc_array::<i64>(&[1, -2, 3_000_000_000]).unwrap();
        assert_eq!(api.sum_i64(fil, values, 3).unwrap(), 2_999_999_999);
        // `const void*` is an untyped `Ptr`.
        let bytes = fil.bytes(b"hello").unwrap();
        assert_eq!(api.hash_bytes(fil, bytes.cast(), 5).unwrap(), 0x4f9f2cab);
    });
}

#[test]
fn variadic_functions_are_called_dynamically() {
    runtime().run(|fil| {
        let api = load(fil);
        // Left out of the interface; call it through `DynCall`.
        let printf = api.library().function::<fn(Ptr<c_char>) -> i32>(fil, "api_printf").unwrap();
        let n = printf
            .dyn_call(fil)
            .arg(fil.c_str("%s-%d\n").unwrap())
            .arg(fil.c_str("x").unwrap())
            .arg(7i32)
            .call::<i32>()
            .unwrap();
        assert_eq!(n, 4);
    });
}

