mod edge_cases {
    include!("generated/edge.rs");

    #[test]
    fn edge_bindings_compile() {
        use edge_ffi::*;
        fn _uses<'f>(n: node<'f>, w: with_cb<'f>) -> (str_<'f>, FilPtr<'f, node<'static>>, FilFn<'f, cb>) {
            (n.label, n.kids[1], w.on_visit)
        }
        use fil_rust::{FilFn, FilPtr};
        let _: Option<Edge> = None;
        let _: Option<&flags> = None;
    }
}
